import type { TokenCounter } from "./interfaces/token-counter.js";

/**
 * 既定の `TokenCounter` 実装（docs/architecture.md §5.9）。
 *
 * モデル固有のトークナイザに依存しない文字数ベースの推定。英語圏で経験的に使われる
 * 「4文字 ≈ 1トークン」という粗い目安を採用する。**常に `counter: 'heuristic'` を返す**
 * ——推定値を実測値の顔で返さない、という契約そのもの。
 */
export const heuristicTokenCounter: TokenCounter = {
  count(text: string): { tokens: number; counter: "heuristic" } {
    const tokens = Math.ceil(text.length / 4);
    return { tokens, counter: "heuristic" };
  },
};

/**
 * TokenCounter — Phase 1（docs/architecture.md §5.9・docs/recall.md §6）。
 *
 * 契約:
 * - 既定実装は文字数ベースの推定（`counter: 'heuristic'`）。
 * - 推定値を実測値の顔で返してはならない——`counter` フィールドは必須。
 */
export interface TokenCounter {
  count(text: string): { tokens: number; counter: "heuristic" | "exact" };
}

import type { Clock } from "@mnemora/core";

/**
 * `now()` が返す時刻を差し替えられる `Clock` 実装(`decay` を `freshness` から分離して測るために足す)。
 *
 * **`Clock` 型は `@mnemora/core` から公開されている**——`packages/core/src/index.ts` が
 * `export * from "./interfaces/clock.js"` しており、`interfaces/clock.ts` の
 * `export interface Clock { now(): Date }` がそのまま外へ出ている(`systemClock`/`fixedClock`
 * も同様に公開)。⟹ 構造的に満たす別形を用意する必要は無く、`@mnemora/core` の `Clock` を
 * そのまま実装する。
 */
export interface MutableClock extends Clock {
  set(at: Date): void;
}

/** 既定の初期値は実時刻(`new Date()`)。 */
export function createMutableClock(initial: Date = new Date()): MutableClock {
  let current = initial;
  return {
    now(): Date {
      return current;
    },
    set(at: Date): void {
      current = at;
    },
  };
}

import type { RecallResult } from "@mnemora/core";

/**
 * `recall()` の返り値のうち、roadmap.md 段階7の完了条件そのものである
 * `omitted` と `usage` を画面に可視化する（PR 本文「omitted と usage を可視化する」）。
 */
export function formatRecall(result: RecallResult, label: string): string {
  const lines: string[] = [];
  lines.push(`--- recall (${label}) ---`);
  lines.push(`memories: ${result.memories.length} 件返却`);
  for (const m of result.memories) {
    lines.push(`  - [${m.retrievedVia}] score=${m.score.total.toFixed(3)} digest="${m.digest}"`);
  }
  lines.push(`omitted (${result.omitted.length} 件):`);
  return lines.join("\n");
}

import type { TokenCounter } from "@mnemora/core";
import type { Conversation } from "./scenario.js";

export interface PathMeasurement {
  chars: number;
  estimatedTokens: number;
  counter: "heuristic" | "exact";
}

/**
 * 経路A（naive）: 会話ログを全部プロンプトへ積む、mnemora を使わない今の普通のやり方。
 */
export function naivePrompt(conversation: Conversation): string {
  return conversation.turns.map((t) => `${t.role}: ${t.text}`).join("\n");
}

export function measureNaive(
  conversation: Conversation,
  tokenCounter: TokenCounter,
): PathMeasurement {
  const text = naivePrompt(conversation);
  const counted = tokenCounter.count(text);
  return { chars: text.length, estimatedTokens: counted.tokens, counter: counted.counter };
}

/**
 * `fillerPairs` 組の filler な user/assistant 往復を、冒頭の事実表明の後に積んだ会話を作る。
 *
 * @param fillerPairs filler の往復数。0以上の整数。
 */
export function buildConversation(fillerPairs: number): Conversation {
  if (!Number.isInteger(fillerPairs) || fillerPairs < 0) {
    throw new Error(
      `buildConversation: fillerPairs は 0 以上の整数である必要がある（実際: ${fillerPairs}）`,
    );
  }

  const turns: ConversationTurn[] = [];
  let index = 0;
  turns.push({ index: index++, role: "user", text: FACT_STATEMENT });
  turns.push({ index: index++, role: "assistant", text: FACT_ACK });
  return { turns, userUtterances: turns.filter((t) => t.role === "user"), query: QUERY_TEXT };
}

/**
 * `index` に対して一意な干し草文を返す(決定的、乱数無し)。
 * 3軸(時間文脈8 × 対象10 × 述語8 = 640通り)の直積で組み立てる——
 * `DEFAULT_HAYSTACK_SIZE` を大きく超えない限り、同じ組み合わせは出ない。
 */
export function buildHaystackUtterance(index: number): string {
  if (!Number.isInteger(index) || index < 0) {
    throw new Error(
      `buildHaystackUtterance: index は 0 以上の整数である必要がある(実際: ${index})`,
    );
  }
  const subject = HAYSTACK_SUBJECT[index % HAYSTACK_SUBJECT.length]!;
  return `${subject}`;
}

/**
 * `gold-<id>` の externalId 規約。`retrieval-quality.ts` の系譜追跡がこれに依存する。
 */
export function goldExternalId(probeId: string): string {
  return `gold-${probeId}`;
}

/** `distractor-<id>` の externalId 規約。 */
export function distractorExternalId(probeId: string): string {
  return `distractor-${probeId}`;
}

/** `filler-NNNN`(4桁ゼロ埋め)の externalId 規約。 */
export function haystackExternalId(index: number): string {
  return `filler-${String(index).padStart(4, "0")}`;
}

